head -c 400 data/venues.json; echo; node -e '
const v=JSON.parse(require("fs").readFileSync("data/venues.json","utf8"));
const list=(Array.isArray(v)?v:Object.values(v)).map(x=>[x.lat??x.latitude,x.lng??x.lon??x.longitude]).filter(p=>p[0]!=null&&p[1]!=null);
const R=6371,rad=d=>d*Math.PI/180;
function km(a,b){const dLat=rad(b[0]-a[0]),dLng=rad(b[1]-a[1]);const h=Math.sin(dLat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
let n=0,over={walk:0,bike:0,car:0};
const sp={walk:10/3,bike:15,car:22};
for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const d=km(list[i],list[j]);n++;for(const m in sp){if(d/sp[m]*60>30)over[m]++;}}
console.log("venues with coords:",list.length,"pairs:",n);
for(const m in over)console.log(m,"pairs where travel>30min:",over[m],(100*over[m]/n).toFixed(1)+"%");
'

