+  34%, 100% { background: #fbfbfe; border-color: transparent; }
+}
+@keyframes iStepNum {
+  0%, 2%    { background: #c7c2e8; }
+  5%, 30%   { background: var(--red); }
+  34%, 100% { background: #c7c2e8; }
+}
+
+.intro-got {
+  font: inherit; font-family: var(--serif); font-weight: 700; font-size: 0.92rem;
+  color: #fff; background: var(--red); border: none; border-radius: 11px;
+  padding: 10px 18px; cursor: pointer;
+  box-shadow: 0 8px 18px rgba(108, 76, 241, 0.24);
+}
+.intro-got:hover { background: var(--red-dark); }
+.intro-got:focus-visible, .intro-x:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
+
+/* Reduced motion gets the loop's *last* frame held still — every element
+   visible, the route drawn — which is exactly the summary the animation
+   spends nine seconds building up to. */
+@media (prefers-reduced-motion: reduce) {
+  .intro-stage *, .intro-step, .intro-step::before { animation: none; }
+  .i-you, .i-dest, .i-pin, .i-verdict { opacity: 1; }
+  .i-ring { opacity: 0.95; transform: scale(1); }
+  .i-route { stroke-dashoffset: 0; }
+  .i-pulse { opacity: 0; }
+  .intro-step { background: #f3f1fe; border-color: #ddd7fb; }
+  .intro-step::before { background: var(--red); }
+}
+
 /* --- Primary CTA (opens the next-commitment picker) --- */
 .cta-card { border: none; box-shadow: none; background: transparent; }
 .cta-card:hover { transform: none; box-shadow: none; }

