// One reusable Playwright driver for this session (see the project RULES.md:
// don't author a fresh throwaway per screenshot).
//
//   node shot.mjs <url> <out.png> [--full] [--wait ms] [--click sel] [--eval "js"]
//   [--clip sel] [--localstorage k=v] [--width N] [--height N]
//
// Launches with no executablePath — PLAYWRIGHT_BROWSERS_PATH is already set in
// this sandbox, so chromium.launch() finds its own browser.
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const argv = process.argv.slice(2);
const [url, out] = argv;
const flag = (name, dflt = null) => {
  const i = argv.indexOf(name);
  return i === -1 ? dflt : argv[i + 1];
};
const has = (name) => argv.includes(name);

const width = Number(flag("--width", 900));
const height = Number(flag("--height", 1000));

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 2 });
const page = await ctx.newPage();

const errors = [];
page.on("console", (m) => {
  if (m.type() !== "error") return;
  const t = m.text();
  // Known-noisy, per RULES.md: the repo ships no favicon, and the browser
  // resets connections on teardown. Neither is an application error.
  if (/favicon\.ico|ERR_CONNECTION_RESET/.test(t)) return;
  errors.push(t);
});
page.on("pageerror", (e) => errors.push(String(e)));

const ls = argv.filter((a, i) => argv[i - 1] === "--localstorage");
if (ls.length) {
  await page.addInitScript((pairs) => {
    for (const p of pairs) {
      const i = p.indexOf("=");
      localStorage.setItem(p.slice(0, i), p.slice(i + 1));
    }
  }, ls);
}

await page.goto(url, { waitUntil: "networkidle" });

const click = flag("--click");
if (click) {
  for (const sel of click.split("|")) {
    await page.click(sel);
    await page.waitForTimeout(250);
  }
}

const js = flag("--eval");
let evalResult;
if (js) evalResult = await page.evaluate(js);

const wait = Number(flag("--wait", 300));
if (wait) await page.waitForTimeout(wait);

const clip = flag("--clip");
if (clip) {
  await page.locator(clip).first().screenshot({ path: out });
} else {
  await page.screenshot({ path: out, fullPage: has("--full") });
}

if (evalResult !== undefined) console.log("eval:", JSON.stringify(evalResult, null, 2));
console.log(errors.length ? `PAGE ERRORS:\n${errors.join("\n")}` : "no page errors");
await browser.close();

