/* Deterministic offline stand-in for Leaflet + Leaflet.markercluster.
 *
 * The sandbox can't reach unpkg.com, and `L is not defined` aborts init() at
 * the first line, so nothing below the map ever renders. The app only ever
 * calls seven Leaflet factories (L.map/tileLayer/marker/divIcon/circle/
 * polyline/markerClusterGroup) and then chains methods on what they return, so
 * a chainable no-op object covers every use without pretending to draw a map.
 */
(function () {
  function chainable() {
    const target = function () { return chainable(); };
    return new Proxy(target, {
      get(_t, prop) {
        if (prop === "then") return undefined;          // don't look thenable
        if (prop === Symbol.toPrimitive) return () => 0;
        if (prop === "length") return 0;
        return chainable();
      },
      apply() { return chainable(); },
      has() { return true; },
    });
  }
  window.L = chainable();
})();

