const stub = readFileSync(new URL("./leaflet-stub.js", import.meta.url), "utf8");
// The pages pin Leaflet with subresource integrity, which (correctly) rejects
// the stub — so strip the integrity attributes out of the served HTML.
await page.route("**/localhost:8000/**", async (route) => {
  const res = await route.fetch();
  const type = res.headers()["content-type"] || "";
  if (!type.includes("text/html")) return route.fulfill({ response: res });
  const body = (await res.text()).replace(/\s+integrity="[^"]*"/g, "");
  route.fulfill({ response: res, body });
});

