  background: linear-gradient(180deg, #6c4cf1, var(--violet-dark));
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(90, 63, 214, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.25);
}
