/* The fold control. `list-style: none` (plus the WebKit pseudo-element) drops
   the native triangle so we can draw our own, which rotates with the state. */
.legend-toggle {
  list-style: none; cursor: pointer; width: fit-content;
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.04em;
  text-transform: uppercase; color: var(--muted);
}
.legend-toggle::-webkit-details-marker { display: none; }
.legend-toggle::before {
  content: ""; width: 0; height: 0;
  border: 4px solid transparent; border-left-color: currentColor;
  border-right-width: 0;
  transition: transform 0.15s ease;
}
.cal-legend[open] .legend-toggle::before { transform: rotate(90deg); }
.legend-toggle:hover { color: var(--ink); }
.legend-toggle:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; border-radius: 5px; }
.cal-legend[open] .legend { margin-top: 10px; }

