input.new_string:
.win-edge::before {
  content: ""; position: absolute; top: 0; bottom: 0; left: 50%; width: 2px;
  margin-left: -1px; background: transparent; transition: background 0.12s ease;
}
.win-edge:hover::before, .win-edge.dragging::before { background: rgba(108, 76, 241, 0.55); }
/* A grip planted halfway down each edge line. The lines themselves are 2px of
   window chrome and read as a boundary, not a control — so the date window got
   resized from the flags up top and these were never touched. The glyph is the
   invitation: a graspable knob, on the line, where the hand already is. */
.win-edge::after {
  content: ""; position: absolute; left: 50%; top: 50%;
  width: 13px; height: 28px; margin-left: -6.5px; transform: translateY(-50%);
  border-radius: 5px;
  background: var(--violet)
    linear-gradient(90deg,
      transparent 0 3.5px, rgba(255, 255, 255, 0.9) 3.5px 5px,
      transparent 5px 8px, rgba(255, 255, 255, 0.9) 8px 9.5px, transparent 9.5px);
  box-shadow: 0 2px 6px rgba(90, 63, 214, 0.4);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.win-edge:hover::after, .win-edge.dragging::after {
  transform: translateY(-50%) scale(1.12);
  box-shadow: 0 3px 10px rgba(90, 63, 214, 0.55);
}

