// Behavioural checks for this change set — the things a screenshot can't show
// (cursors, persistence, arming, caching). Complements shot.mjs, which is for
// looking at pixels.
//
//   node check.mjs
import { readFileSync } from "node:fs";
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const BASE = "http://localhost:8000";
const stub = readFileSync(new URL("./leaflet-stub.js", import.meta.url), "utf8");

const results = [];
const check = (name, pass, detail = "") => {
  results.push({ name, pass, detail });
  console.log(`${pass ? "PASS" : "FAIL"}  ${name}${detail ? ` — ${detail}` : ""}`);
};

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });

async function newPage() {
  const page = await ctx.newPage();
  await page.route("**://unpkg.com/**", (r) =>
    r.fulfill(r.request().url().endsWith(".css")
      ? { contentType: "text/css", body: "" }
      : { contentType: "text/javascript", body: stub }));
  await page.route("**://fonts.googleapis.com/**", (r) => r.fulfill({ contentType: "text/css", body: "" }));
  await page.route("**://fonts.gstatic.com/**", (r) => r.abort());
  await page.route("**/localhost:8000/**", async (route) => {
    const res = await route.fetch();
    const type = res.headers()["content-type"] || "";
    if (!type.includes("text/html")) return route.fulfill({ response: res });
    route.fulfill({ response: res, body: (await res.text()).replace(/\s+integrity="[^"]*"/g, "") });
  });
  return page;
}

// ---------------------------------------------------------------- plan page
let page = await newPage();
const requested = [];
page.on("request", (r) => requested.push(r.url()));
await page.goto(`${BASE}/plan/`, { waitUntil: "networkidle" });
await page.setInputFiles("#csvInput", new URL("./favs.csv", import.meta.url).pathname);
await page.waitForSelector(".lane", { timeout: 10000 });
await page.waitForTimeout(1200);

// --- descriptions sidecar
check("descriptions sidecar is fetched",
  requested.some((u) => u.includes("descriptions.min.json")));
const descCount = await page.evaluate(() => window.__descCount ?? null);
const tipHasDesc = await page.evaluate(async () => {
  const cell = document.querySelector(".lane .cell[data-day]");
