  const before = getComputedStyle(lane.querySelector(".lane-label")).cursor;
  label.click(); // locks the show
  const after = getComputedStyle(lane.querySelector(".lane-label")).cursor;
  return { before, after, forced: lane.classList.contains("lane--forced") };
});
