1	// Node test for the pure CSV/ICS exporters. No dependencies — plain
2	// node:test + node:assert. Run from /workspace/edfringenow with:
3	//   node plan/lib/__tests__/itinerary.test.mjs
4	
5	import { test } from "node:test";
6	import assert from "node:assert/strict";
7	
8	import { buildSchedule } from "../engine.js";
9	import { toCsv, toIcs, slotEndTime } from "../itinerary.js";
10	
11	// One synthetic show with a comma in its title (to exercise CSV quoting) and a
12	// known duration so start/end are predictable.
13	const SHOWS = [
14	  {
15	    slug: "hello-goodbye",
16	    title: "Hello, Goodbye",
17	    genre: "Comedy",
18	    duration: 60,
19	    venue: "V1",
20	    venueName: "Venue One",
21	    room: "Studio",
22	    performances: [
23	      { date: "2026-08-10", start: "19:30", soldOut: false, status: "TICKETS_AVAILABLE" },
24	    ],
25	  },
26	];
27	
28	const schedule = buildSchedule(SHOWS, {
29	  windowStart: "2026-08-10T00:00",
30	  windowEnd: "2026-08-10T23:59",
31	});
32	
33	test("buildSchedule produced exactly the one slot with derived end time", () => {
34	  assert.equal(schedule.scheduled.length, 1);
35	  const slot = schedule.scheduled[0];
36	  assert.equal(slot.startTime, "19:30");
37	  assert.equal(slotEndTime(slot), "20:30"); // 19:30 + 60min duration
38	});
39	
40	test("toCsv: header + one quoted row with the right columns", () => {
41	  const csv = toCsv(schedule.scheduled);
42	  const lines = csv.split("\r\n");
43	  assert.equal(lines[0], "Date,Day,Start,End,Show,Genre,Venue,Room,Status,Tickets");
44	  // Title has a comma → must be quoted; Mon 10 Aug 2026.
45	  assert.ok(lines[1].startsWith("2026-08-10,Mon,19:30,20:30,"), lines[1]);
46	  assert.ok(lines[1].includes('"Hello, Goodbye"'), "comma title should be quoted");
47	  assert.ok(lines[1].includes("Comedy"));
48	  assert.ok(lines[1].includes("Venue One"));
49	});
50	
51	test("toCsv: empty schedule yields just the header", () => {
52	  assert.equal(toCsv([]), "Date,Day,Start,End,Show,Genre,Venue,Room,Status,Tickets");
53	});
54	
55	test("toIcs: well-formed VCALENDAR with one floating-time VEVENT", () => {
56	  const ics = toIcs(schedule.scheduled, { now: new Date(Date.UTC(2026, 6, 22, 12, 0, 0)) });
57	  assert.ok(ics.startsWith("BEGIN:VCALENDAR\r\n"));
58	  assert.ok(ics.trimEnd().endsWith("END:VCALENDAR"));
59	  assert.equal((ics.match(/BEGIN:VEVENT/g) || []).length, 1);
60	  assert.equal((ics.match(/END:VEVENT/g) || []).length, 1);
61	  // Floating local time (no trailing Z) at the Edinburgh wall clock.
62	  assert.ok(ics.includes("DTSTART:20260810T193000"), ics);
63	  assert.ok(ics.includes("DTEND:20260810T203000"), ics);
64	  // DTSTAMP is the UTC export instant we passed in.
65	  assert.ok(ics.includes("DTSTAMP:20260722T120000Z"), ics);
66	  // Comma / other specials in SUMMARY are backslash-escaped per RFC-5545.
67	  assert.ok(ics.includes("SUMMARY:Hello\\, Goodbye"), ics);
68	});
69	
70	test("toIcs: UID is stable for the same slot across two exports", () => {
71	  const a = toIcs(schedule.scheduled, { now: new Date(Date.UTC(2026, 6, 22)) });
72	  const b = toIcs(schedule.scheduled, { now: new Date(Date.UTC(2026, 6, 23)) });
73	  const uidA = a.match(/UID:(.+)/)[1];
74	  const uidB = b.match(/UID:(.+)/)[1];
75	  assert.equal(uidA, uidB); // UID must not depend on export time
76	  assert.match(uidA, /^hello-goodbye-20260810T193000@edfringenow\.com/);
77	});

