1	/* ===================== Design tokens ===================== */
2	:root {
3	  /* Fresh & Minimal skin (design direction #6). Token NAMES are kept so the
4	     existing rules keep resolving; VALUES retuned to a clean, modern
5	     violet-on-white theme. --serif now holds a sans (Plus Jakarta Sans) — the
6	     name is a historical hook, not a promise of a serif face. */
7	  --red: #6c4cf1;        /* primary action — violet */
8	  --red-dark: #5a3fd6;
9	  --gold: #6c4cf1;       /* selection / focus accent — violet */
10	  --blue: #6c4cf1;       /* destination / user pin — violet */
11	  --blue-dark: #5a3fd6;
12	  --pink: #ef4444;       /* warning red — debug chip only */
13	  --ink: #101828;        /* near-black */
14	  --paper: #ffffff;      /* card surface */
15	  --bg: #f7f8fa;         /* page background */
16	  --muted: #667085;
17	  --line: #eaecf0;
18	  --yellow-badge: #f4d645;
19	  --ok: #059669;         /* success / "fits" — Fresh green (accents, borders) */
20	  --ok-text: #047857;    /* success text — darker for AA contrast on white/tint */
21	  --ok-bg: #e6f7ee;      /* success badge background */
22	  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
23	  --shadow-offset: 6px;
24	  --maxw: 1120px;
25	  --radius: 16px;
26	  --serif: "Plus Jakarta Sans", "Plus Jakarta Sans Fallback", system-ui, sans-serif;
27	  font-synthesis: none;
28	}
29	
30	/* Metric-matched fallback faces. Until the web fonts arrive, text is laid out
31	   in local Arial *stretched to the web font's own metrics* (size-adjust +
32	   ascent/descent overrides), so the swap to Inter / Plus Jakarta Sans reflows
33	   almost nothing — this is what keeps CLS out of the "needs improvement" band.
34	   Override values are the standard next/font-generated set for each family. */
35	@font-face {
36	  font-family: "Inter Fallback";
37	  src: local("Arial");
38	  size-adjust: 107.40%;
39	  ascent-override: 90.20%;
40	  descent-override: 22.48%;
41	  line-gap-override: 0%;
42	}
43	@font-face {
44	  font-family: "Plus Jakarta Sans Fallback";
45	  src: local("Arial");
46	  size-adjust: 103.36%;
47	  ascent-override: 103.8%;
48	  descent-override: 22.2%;
49	  line-gap-override: 0%;
50	}
51	
52	/* Which web-font WEIGHTS load is set by the Google Fonts <link> in each page's
53	   <head> — and that link is duplicated across all four HTML pages (index,
54	   privacy, terms, accessibility). Keep the loaded weights in sync with the
55	   weights this stylesheet actually uses: add a weight here, add it to all four
56	   links; stop using one, trim it from all four (an unused weight is font files
57	   downloaded for nothing — that's why 500 was dropped). Currently 400/600/700/800. */
58	
59	* { box-sizing: border-box; }
60	
